const jobId = $('Validate Input').first().json.jobId;
const narration = $('Extract Narration Text').first().json;
const localPath = '/data/jobs/' + jobId + '/narration.wav';
const fs = require('fs'); const { spawnSync } = require('child_process');
const MINIMUM_DURATION_TOLERANCE_SECONDS = 0.5; // Probe/codec rounding within this margin is materially at the minimum.
const probeDuration = () => {
  const probe = spawnSync('ffprobe', ['-v','error','-show_entries','format=duration','-of','default=noprint_wrappers=1:nokey=1',localPath], {encoding:'utf8'});
  const duration = parseFloat(probe.stdout.trim());
  if (probe.error || probe.status !== 0 || !Number.isFinite(duration) || duration <= 0) throw new Error('AUDIO_DURATION_INVALID');
  return duration;
};
if (!fs.existsSync(localPath)) throw new Error('Audio file not found: ' + localPath);
const actualDuration = probeDuration();
const minimumDuration = Number(narration.minimumDuration); const maximumDuration = Number(narration.maximumDuration);
let targetDuration = actualDuration;
if (actualDuration < minimumDuration) targetDuration = actualDuration >= minimumDuration - MINIMUM_DURATION_TOLERANCE_SECONDS ? actualDuration : minimumDuration;
if (actualDuration > maximumDuration) targetDuration = maximumDuration;
const ratio = actualDuration / targetDuration;
if (ratio < 0.5 || ratio > 2) throw new Error('AUDIO_DURATION_CORRECTION_UNSAFE');
if (ratio !== 1) {
  const tempPath = localPath + '.corrected.wav';
  const result = spawnSync('ffmpeg', ['-y','-i',localPath,'-af','atempo=' + ratio,'-ar','24000',tempPath], {encoding:'utf8', timeout:60000});
  if (result.error || result.status !== 0) throw new Error('AUDIO_DURATION_CORRECTION_FAILED');
  fs.copyFileSync(tempPath, localPath); fs.unlinkSync(tempPath);
}
const verifiedDuration = Math.round(probeDuration() * 100) / 100;
if (verifiedDuration < minimumDuration - MINIMUM_DURATION_TOLERANCE_SECONDS || verifiedDuration > maximumDuration) throw new Error('NARRATION_DURATION_OUT_OF_RANGE');
const fileSize = fs.statSync(localPath).size;
if (!Number.isFinite(fileSize) || fileSize < 0) throw new Error('AUDIO_FILE_SIZE_INVALID');
return [{ json: { jobId, local_path: localPath, file_size: fileSize, actual_duration: verifiedDuration, corrected_duration: verifiedDuration } }];

const input = $json.body ?? $json;
const jobId = input.jobId;
if (!jobId || !/^[0-9a-f-]{36}$/i.test(jobId)) throw new Error('Invalid jobId');
return [{json: {...input, jobId}}];

const rows = $input.first().json;
const job = Array.isArray(rows) ? rows[0] : rows;
if (!job?.script_json) throw new Error('No script found for job');
const script = job.script_json;
const text = String(Array.isArray(script.scenes) ? script.scenes.map(scene => scene.narration).filter(Boolean).join(' ') : '').trim();
if (!text) throw new Error('No narration text available');
const sceneDurations = Array.isArray(script.scenes) ? script.scenes.map(scene => Number(scene.durationSeconds)) : [];
if (!sceneDurations.length || sceneDurations.some(duration => !Number.isFinite(duration) || duration <= 0)) throw new Error('INVALID_SCENE_DURATION');
const durationValidation = script.durationValidation;
const audioMode = job.audio_mode || job.brief_json?.audioMode || 'automatic';
const minimumDuration = Number(durationValidation?.minimumDuration);
const maximumDuration = Number(durationValidation?.maximumDuration);
const estimatedDurationSeconds = Number(durationValidation?.estimatedDurationSeconds);
const requestedDuration = Number(durationValidation?.requestedDuration);
if (audioMode !== 'custom_audio' && (!Number.isFinite(minimumDuration) || !Number.isFinite(maximumDuration) || !Number.isFinite(estimatedDurationSeconds) || minimumDuration <= 0 || maximumDuration < minimumDuration)) throw new Error('NARRATION_DURATION_VALIDATION_REQUIRED');
const wordCount = text.split(/\s+/).filter(Boolean).length;
const tone = String(job.brief_json?.voiceTone || '').trim();
const voices = { 'Warm narrator': 'af_heart', 'Studio neutral': 'am_michael', 'Energetic guide': 'af_nova' };
return [{ json: { jobId: job.id, text, ttsVoice: voices[tone] || 'af_heart', requestedDuration, minimumDuration, maximumDuration, estimatedDurationSeconds, wordCount, audioMode, sceneDuration: Math.round(sceneDurations.reduce((sum, duration) => sum + duration, 0) * 100) / 100 } }];

const jobId = $('Validate Input').first().json.jobId;
const input = $input.first();
const binaryData = input.binary?.data;
if (!binaryData?.data) {
  const jsonResponse = input.json;
  if (jsonResponse?.audio_url || jsonResponse?.public_url) return [{ json: { jobId, audio_url: jsonResponse.audio_url || jsonResponse.public_url, local_path: null, file_size: null } }];
  throw new Error('No binary or audio URL received from TTS');
}
const localPath = '/data/jobs/' + jobId + '/narration.wav';
return [{ json: { jobId, local_path: localPath, file_size: Buffer.from(binaryData.data, 'base64').length }, binary: input.binary }];

