const input = $json.body ?? $json;
const jobId = input.jobId ?? input.id;
if (!jobId || !input.workerId || !input.leaseToken || input.attemptNumber == null || input.pipelineRevision == null) throw new Error('LEASE_CONTEXT_REQUIRED');
const stage = 'generate_voice';
const itemKey = input.itemKey ?? ('job' === 'scene_set' ? 'all-scenes' : 'job');
