return [{json: {...input, jobId, stage, itemKey, stageHashInput: canonical, workerId: input.workerId, leaseToken: input.leaseToken, attemptNumber: Number(input.attemptNumber), pipelineRevision: Number(input.pipelineRevision)}}];

const {stageHashInput, ...context} = $('Hash Stage Input').first().json;
const result = $json;
return [{json: {...context, stageState: result.state, stageRunId: result.stage_run_id, runToken: result.run_token, cachedOutput: result.output}}];

const context = $('Merge Stage Context').first().json;
if ($json.permitted !== true) throw new Error('EXTERNAL_ATTEMPT_LIMIT');
return [{json: {...context, externalAttempt: $json.attempt_number}}];

const context = $('Merge Stage Context').first().json;
if (context.stageState !== 'CACHED_SUCCESS') throw new Error('STAGE_RECONCILIATION_REQUIRED');
return [{json: {success: true, cached: true, jobId: context.jobId, stage: context.stage, stageRunId: context.stageRunId, output: context.cachedOutput}}];

const rawJob = $('Get Script').first().json;
const originalJob = Array.isArray(rawJob) ? rawJob[0] : rawJob;
const input = $('Read Custom Audio File').first();
if (!input.binary?.data) {
  throw new Error('No binary data received from Read Custom Audio File');
}
const uploadedDuration = originalJob.uploaded_audio_duration || originalJob.effective_duration;
if (!uploadedDuration) {
  throw new Error('Uploaded audio duration not found in job');
}
const fileSize = Number(input.binary.data.fileSize) || 0;
return [{
  json: { ...originalJob, jobId: originalJob.id, local_path: '/data/jobs/' + originalJob.id + '/narration.wav', uploaded_duration: uploadedDuration, file_size: fileSize },
  binary: input.binary
}];

const job = $('Get Script').first().json;
const source = Array.isArray(job) ? job[0] : job;
const audioMode = source.audio_mode || source.brief_json?.audioMode || 'automatic';
const automatic = audioMode === 'custom_audio' ? null : $('Correct Audio Duration').first().json;
const effectiveDuration = audioMode === 'custom_audio' ? Number(source.effective_duration || source.uploaded_audio_duration) : Number(automatic.corrected_duration);
if (!Number.isFinite(effectiveDuration) || effectiveDuration <= 0) throw new Error('EFFECTIVE_DURATION_REQUIRED');
